-- Check if there are treatmentoutcomes without matching treatmentbasics
SELECT COUNT(*) FROM treatmentoutcomes to2 WHERE NOT EXISTS (
  SELECT 1 FROM treatmentbasics tb WHERE to2.txref = tb.txkey
);

WITH tes AS (
  SELECT f.fackey, AVG(CASE WHEN tb.therapy_details->>'engagement' = 'High' THEN 3::numeric WHEN tb.therapy_details->>'engagement' = 'Medium' THEN 2::numeric WHEN tb.therapy_details->>'engagement' = 'Low' THEN 1::numeric WHEN tb.therapy_details->>'engagement' = 'Non-compliant' THEN 0::numeric END) as tes FROM facilities f JOIN encounters e ON f.fackey = e.facid JOIN treatmentbasics tb ON e.enckey = tb.encref GROUP BY f.fackey
),
rti_data AS (
  SELECT f.fackey, AVG(CASE WHEN to2.funcimpv = 'Significant' THEN 3::numeric WHEN to2.funcimpv = 'Moderate' THEN 2::numeric WHEN to2.funcimpv = 'Minimal' THEN 1::numeric END) * (COUNT(CASE WHEN to2.txadh IN ('High', 'Medium') THEN 1 END)::numeric / COUNT(*)) as rti FROM facilities f JOIN encounters e ON f.fackey = e.facid JOIN treatmentbasics tb ON e.enckey = tb.encref JOIN treatmentoutcomes to2 ON tb.txkey = to2.txref GROUP BY f.fackey
),
frai_data AS (
  SELECT fackey, support_and_resources->>'community_resources' as community_resource_level, AVG(CASE WHEN support_and_resources->>'community_resources' = 'Comprehensive' THEN 3::numeric WHEN support_and_resources->>'community_resources' = 'Adequate' THEN 2::numeric WHEN support_and_resources->>'community_resources' = 'Limited' THEN 1::numeric END) as frai FROM facilities GROUP BY fackey, support_and_resources
)
SELECT t.fackey as facility_id, ROUND(t.tes, 2) as tes, ROUND(r.rti, 2) as rti, f.community_resource_level, ROUND(f.frai, 2) as frai FROM tes t JOIN rti_data r ON t.fackey = r.fackey JOIN frai_data f ON t.fackey = f.fackey WHERE t.tes > 2.0 AND r.rti < 0.8 ORDER BY t.fackey;

