  SELECT f.fackey, AVG(CASE WHEN tb.therapy_details->>'engagement' = 'High' THEN 3::numeric WHEN tb.therapy_details->>'engagement' = 'Medium' THEN 2::numeric WHEN tb.therapy_details->>'engagement' = 'Low' THEN 1::numeric WHEN tb.therapy_details->>'engagement' = 'Non-compliant' THEN 0::numeric END) as tes FROM facilities f JOIN encounters e ON f.fackey = e.facid JOIN treatmentbasics tb ON e.enckey = tb.encref GROUP BY f.fackey
),
rti_data AS (
  SELECT f.fackey, AVG(CASE WHEN to2.funcimpv = 'Significant' THEN 3::numeric WHEN to2.funcimpv = 'Moderate' THEN 2::numeric WHEN to2.funcimpv = 'Minimal' THEN 1::numeric END) * (COUNT(CASE WHEN to2.txadh IN ('High', 'Medium') THEN 1 END)::numeric / COUNT(*)) as rti FROM facilities f JOIN encounters e ON f.fackey = e.facid JOIN treatmentbasics tb ON e.enckey = tb.encref JOIN treatmentoutcomes to2 ON tb.txkey = to2.txref GROUP BY f.fackey
),
frai_data AS (
  SELECT DISTINCT fackey, support_and_resources->>'community_resources' as community_resource_level, CASE WHEN support_and_resources->>'community_resources' = 'Comprehensive' THEN 3::numeric WHEN support_and_resources->>'community_resources' = 'Adequate' THEN 2::numeric WHEN support_and_resources->>'community_resources' = 'Limited' THEN 1::numeric END as frai FROM facilities
)
SELECT t.fackey as facility_id, t.tes, r.rti, f.community_resource_level, f.frai FROM tes t JOIN rti_data r ON t.fackey = r.fackey JOIN frai_data f ON t.fackey = f.fackey WHERE t.tes > 2.0 AND r.rti < 0.8 ORDER BY t.fackey;
